import random

from locust import FastHttpUser, task

# HW6 Part II: every user searches GET /products/search?q=... with FastHttpUser.
# (locustfile.py and locustfile_fast.py are the HW5 GET/POST tests.)
#
#   Test 1 (baseline):       5 users for 2 minutes
#   Test 2 (breaking point): 20 users for 3 minutes
#
# Set users, ramp up, and run time (Advanced options) in the web UI.

# Common terms that match the product names ("Product Alpha 1") or category
# names generated by product-service.go. How many match does not change the
# cost, since every search checks exactly 100 products.
SEARCH_TERMS = ["electronics", "books", "home", "toys", "alpha", "beta", "product", "sports"]


class SearchUser(FastHttpUser):
    # No wait_time: each user sends its next search as soon as the last one
    # finishes, so the user count sets how hard the server is pushed.

    @task
    def search(self):
        q = random.choice(SEARCH_TERMS)
        # One name for all terms, so Locust reports them as one row.
        self.client.get(f"/products/search?q={q}", name="/products/search?q=[term]")
